// https://en.wikipedia.org/wiki/Euler_method
// https://en.wikipedia.org/wiki/Backward_Euler_method
// https://en.wikipedia.org/wiki/Semi-implicit_Euler_method
// https://en.wikipedia.org/wiki/Verlet_integration
// https://en.wikipedia.org/wiki/Symplectic_integrator

float dt = 1. / 10.; // time per pixel
float g  = 10.; // gravity
float k  = 5.; // spring constant
float q  = 0.; // position
float p  = 10.; // momentum

float V () { return (.5 * k * q + g) * q; } // potential energy (only depends on position)
float V0() { return k * q + g; }

float T () { return .5 * p * p; } // kinetic energy (only depends on momentum)
float T0() { return p; }

float H() { return V() + T(); } // separable hamiltonian (= total energy)

vec2 reference(float t)
{
    float omega = sqrt(k), o = -g / k, r = sqrt(2. * H() * k + g * g) / k;
    t *= omega;
    t += atan(q - o, p / omega);
    return vec2(o + sin(t) * r, cos(t) * r * omega);
}

void exact()
{
    float omega = sqrt(k), a = omega * dt, o = -g / k, r = sqrt(2. * H() * k + g * g) / k;
    vec2 d = vec2(q - o, p / omega) * mat2(cos(a), sin(a), -sin(a), cos(a));
    q = d.x + o;
    p = d.y * omega;
}

void euler()
{
    vec2 d = vec2(T0(), -V0()) * dt;
    q += d.x;
    p += d.y;
}

void eulerImplicit()
{
    vec3 z = inverse(mat3(1) - mat3(0, -k, 0,  1, 0, 0,  0, -g, 0) * dt) * vec3(q, p, 1);
    q = z.x;
    p = z.y;
}

void eulerSymplectic()
{
    q += T0() * dt;
    p -= V0() * dt;
}


#if 0
    float q1;
    void initVerlet()
    {
        q1 = q + dt * (p - dt * .5 * V0());
    }
    void verlet()
    {
        float qp = q;
        q = q1;
        q1 = 2. * q - qp - dt * dt * V0();
        p = (q1 - qp) / dt / 2.;
    }
#else
    void initVerlet() {}
    void verlet() // symplectic 2nd-order
    {
        p -= V0() * dt / 2.;
        q += T0() * dt;
        p -= V0() * dt / 2.;
    }
#endif

void symplectic4()
{
    float t = pow(2., 1. / 3.);
    float d1 = 1. / (2. - t), d2 = -t / (2. - t), d3 = d1; // sum to 1
    float c1 = d1 / 2., c2 = (1. - t) / (2. * (2. - t)), c3 = c2, c4 = c1; // sum to 1
    q += T0() * c1 * dt;
    p -= V0() * d1 * dt;
    q += T0() * c2 * dt;
    p -= V0() * d2 * dt;
    q += T0() * c3 * dt;
    p -= V0() * d3 * dt;
    q += T0() * c4 * dt;
}

vec2 uv;
float line(vec2 a, vec2 b)
{
    b -= a;
    return length(uv - a - b * clamp(dot(uv - a, b) / dot(b, b), 0., 1.));
}

void mainImage(out vec4 fragColor, vec2 fragCoord)
{
    float n = 6.;
    int method = int(n - 1. - floor(fragCoord.y / (iResolution.y / n)));
    uv = vec2(fragCoord.x, floor(mod(fragCoord.y, iResolution.y / n) - iResolution.y / n * .5));

    float e = 1e9, r = 1e9, s = iResolution.y / n / 20.;

    for (float i=0. ; i<iResolution.x ; i++)
    {
        vec2 a = vec2(i, reference(i * dt).x * s);
        vec2 b = vec2(i + 1., reference(i * dt + dt).x * s);
        e = min(e, line(a, b));
    }
    if (method == 3) initVerlet();
    for (float i=0. ; i<iResolution.x ; i++)
    {
        vec2 a = vec2(i, q * s);
        if (method == 0) euler();
        if (method == 1) eulerImplicit();
        if (method == 2) eulerSymplectic();
        if (method == 3) verlet();
        if (method == 4) symplectic4();
        if (method == 5) exact();
        vec2 b = vec2(i + 1., q * s);
        r = min(r, line(a, b));
    }

    fragColor = vec4(1);
    fragColor = mix(fragColor, vec4(.5,.5,.5,1), clamp(1. - abs(uv.y), 0., 1.));
    fragColor = mix(fragColor, vec4(1,0,0,1), clamp(1. - e, 0., 1.));
    fragColor = mix(fragColor, vec4(0,0,0,1), clamp(1. - r, 0., 1.));
    fragColor = sqrt(fragColor);
}
